import React, { useState } from 'react';
import { ShoppingBag, BookOpen, Star, Sparkles, ExternalLink, Check, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
