import React, { useState } from 'react';
import { Navbar } from '@/components/Navbar';
import { Hero } from '@/components/Hero';
import { StartHere } from '@/components/StartHere';
import { GaiaMethod } from '@/components/GaiaMethod';
import { ClubGaia } from '@/components/ClubGaia';
import { About } from '@/components/About';
import { CoursesAndShop } from '@/components/CoursesAndShop';
import { PodcastSection } from '@/components/PodcastSection';
import { Testimonials } from '@/components/Testimonials';
import { ContactSection } from '@/components/ContactSection';
import { Footer } from '@/components/Footer';

import { X, Sparkles, CheckCircle, ShieldCheck, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';

export default function App() {
  const [isClubModalOpen, setIsClubModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<{ title: string; price: string } | null>(null);

  const handleOpenClub = () => {
    setIsClubModalOpen(true);
  };

  const handleScrollToQuiz = () => {
    const el = document.getElementById('comeca-aqui');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleScrollToContact = () => {
    const el = document.getElementById('contactos');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleOpenProduct = (title: string, price: string) => {
    setSelectedProduct({ title, price });
  };

  return (
    <div className="min-h-screen bg-[#FDFBF7] text-[#6B4F3F] font-sans relative selection:bg-[#B86F4B]/20 selection:text-[#6B4F3F]">
      {/* Barra de Navegação */}
      <Navbar
        onOpenClubModal={handleOpenClub}
        onOpenContactModal={handleScrollToContact}
      />

      {/* Conteúdo Principal */}
      <main>
        {/* Seção Hero */}
        <Hero
          onOpenClubModal={handleOpenClub}
          onScrollToQuiz={handleScrollToQuiz}
        />

        {/* Começa por Aqui: Quiz & Autoavaliação */}
        <StartHere
          onOpenClubModal={handleOpenClub}
          onOpenContactModal={handleScrollToContact}
        />

        {/* Sobre Mim */}
        <About onOpenContactModal={handleScrollToContact} />

        {/* Método GAIA */}
        <GaiaMethod onOpenClubModal={handleOpenClub} />

        {/* Clube GAIA */}
        <ClubGaia onOpenClubModal={handleOpenClub} />

        {/* Cursos & Loja */}
        <CoursesAndShop onOpenProductModal={handleOpenProduct} />

        {/* Podcast Intestino Sem Filtros */}
        <PodcastSection />

        {/* Testemunhos de Pacientes */}
        <Testimonials />

        {/* Formulário e Informações de Contacto */}
        <ContactSection />
      </main>

      {/* Rodapé Oficial */}
      <Footer onOpenClubModal={handleOpenClub} />

      {/* Modal / Checkout Simulado do Clube GAIA */}
      {isClubModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#FDFBF7] max-w-lg w-full rounded-3xl p-6 sm:p-8 border-2 border-[#B86F4B] shadow-2xl relative space-y-6 text-left">
            <button
              onClick={() => setIsClubModalOpen(false)}
              className="absolute top-4 right-4 p-2 rounded-full text-[#6B4F3F] hover:bg-[#D8C4A8]/30 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="space-y-2">
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#B86F4B]/15 text-[#B86F4B] text-xs font-bold uppercase tracking-wider">
                <Sparkles className="w-3.5 h-3.5" />
                <span>Inscrição Oficial</span>
              </div>
              <h3 className="font-serif text-2xl font-bold text-[#3F5B45]">
                Bem-vinda ao Clube GAIA
              </h3>
              <p className="text-xs text-[#6B4F3F]/80">
                Garante o teu acesso à comunidade, aos encontros quinzenais e ao protocolo completo anti-inflamatório.
              </p>
            </div>

            <div className="p-4 rounded-2xl bg-[#3F5B45]/10 border border-[#3F5B45]/20 space-y-2">
              <div className="flex items-center justify-between">
                <span className="font-serif text-xl font-bold text-[#3F5B45]">29€ / mês</span>
                <span className="text-[11px] text-[#A67878] font-bold uppercase">Sem fidelização</span>
              </div>
              <p className="text-xs text-[#6B4F3F]">
                Cobrança mensal segura com renovação automática e cancelamento em 1 clique a qualquer momento.
              </p>
            </div>

            <div className="space-y-2 text-xs text-[#6B4F3F]">
              <div className="flex items-center gap-2">
                <CheckCircle className="w-4 h-4 text-[#3F5B45]" />
                <span>Acesso imediato à plataforma de alunas e vídeos</span>
              </div>
              <div className="flex items-center gap-2">
                <CheckCircle className="w-4 h-4 text-[#3F5B45]" />
                <span>Entrada no grupo exclusivo da comunidade</span>
              </div>
              <div className="flex items-center gap-2">
                <CheckCircle className="w-4 h-4 text-[#3F5B45]" />
                <span>Garantia de satisfação de 14 dias</span>
              </div>
            </div>

            <div className="pt-2 space-y-3">
              <Button
                onClick={() => {
                  alert('A redirecionar para a página segura de pagamento da Stripe/MB Way...');
                  setIsClubModalOpen(false);
                }}
                className="w-full bg-[#B86F4B] hover:bg-[#a15f3e] text-white font-bold py-6 rounded-xl text-base shadow-lg flex items-center justify-center gap-2"
              >
                <span>Finalizar Inscrição no Clube</span>
                <ArrowRight className="w-4 h-4" />
              </Button>
              <p className="text-center text-[11px] text-[#A67878] flex items-center justify-center gap-1">
                <ShieldCheck className="w-3.5 h-3.5" />
                <span>Pagamento 100% encriptado e seguro</span>
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Modal / Compra Rápida de Produto/Curso */}
      {selectedProduct && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#FDFBF7] max-w-md w-full rounded-3xl p-6 sm:p-8 border border-[#D8C4A8] shadow-2xl relative space-y-5 text-left">
            <button
              onClick={() => setSelectedProduct(null)}
              className="absolute top-4 right-4 p-2 rounded-full text-[#6B4F3F] hover:bg-[#D8C4A8]/30 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="space-y-1">
              <span className="text-[11px] font-bold text-[#B86F4B] uppercase tracking-wider">
                Aquisição Segura
              </span>
              <h3 className="font-serif text-xl font-bold text-[#3F5B45]">
                {selectedProduct.title}
              </h3>
            </div>

            <div className="p-3.5 rounded-xl bg-[#D8C4A8]/20 flex items-center justify-between">
              <span className="text-xs font-medium text-[#6B4F3F]">Valor Total:</span>
              <span className="font-serif text-2xl font-bold text-[#3F5B45]">{selectedProduct.price}</span>
            </div>

            <p className="text-xs text-[#6B4F3F]/80 leading-relaxed">
              O acesso aos ficheiros e à plataforma será enviado diretamente para o teu e-mail após confirmação do pagamento (Cartão, MB WAY ou Multibanco).
            </p>

            <Button
              onClick={() => {
                alert(`A redirecionar para o checkout seguro de "${selectedProduct.title}"...`);
                setSelectedProduct(null);
              }}
              className="w-full bg-[#3F5B45] hover:bg-[#2d4232] text-white font-bold py-3.5 rounded-xl text-sm"
            >
              Prosseguir para o Pagamento
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

