                      </>
                    ) : (
                      <>
                        <Play className="w-3.5 h-3.5 fill-current" />
                        <span>Ouvir Prévia</span>
                      </>
                    )}
                  </button>

                  <a
                    href={ep.spotifyUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-xs text-[#B86F4B] font-semibold hover:underline flex items-center gap-1"
                  >
                    <span>Episódio Completo</span>
                    <ArrowRight className="w-3 h-3" />
                  </a>
                </div>
              </Card>
            );
          })}
        </div>
      </div>
    </section>
  );
};

