import React, { useState } from 'react';
import { Navbar } from '@/components/Navbar';
import { Hero } from '@/components/Hero';
import { GaiaMethod } from '@/components/GaiaMethod';
import { ClubGaia } from '@/components/ClubGaia';
import { MenopausaCourse } from '@/components/MenopausaCourse';
import { FreeMapSection } from '@/components/FreeMapSection';
import { PersonalizedCare } from '@/components/PersonalizedCare';
import { PodcastSection } from '@/components/PodcastSection';
import { About } from '@/components/About';
import { Testimonials } from '@/components/Testimonials';
import { ContactSection } from '@/components/ContactSection';
import { Footer } from '@/components/Footer';

import { X, Sparkles, CheckCircle2, ShieldCheck, ArrowRight, MessageCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';

export default function App() {
  // Estado de navegação de páginas / vistas
  const [currentView, setCurrentView] = useState<'home' | 'menopausa' | 'care'>('home');
  const [isClubModalOpen, setIsClubModalOpen] = useState(false);
  const [isCourseCheckoutOpen, setIsCourseCheckoutOpen] = useState(false);

  const handleOpenClub = () => {
    setIsClubModalOpen(true);
  };

  const handleNavigateToCourse = () => {
    setCurrentView('menopausa');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigateToCare = () => {
    setCurrentView('care');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigateHome = () => {
    setCurrentView('home');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleScrollToFreeMap = () => {
    if (currentView !== 'home') {
      setCurrentView('home');
      setTimeout(() => {
        const el = document.getElementById('mapa-gratuito');
        if (el) el.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } else {
      const el = document.getElementById('mapa-gratuito');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen bg-[#FDFBF7] text-[#6B4F3F] font-sans relative selection:bg-[#B86F4B]/20 selection:text-[#6B4F3F]">
      {/* Barra de Navegação Superior */}
      <Navbar
        onOpenClubModal={handleOpenClub}
        onNavigateToCourse={handleNavigateToCourse}
        onNavigateToCare={handleNavigateToCare}
        onNavigateHome={handleNavigateHome}
      />

      {/* Conteúdo Renderizado com Base na Estratégia das 4 Portas */}
      <main>
        {currentView === 'home' && (
          <>
            {/* Bloco 1 & 2: Hero com as 4 Portas */}
            <Hero
              onOpenClubModal={handleOpenClub}
              onNavigateToCourse={handleNavigateToCourse}
              onScrollToFreeMap={handleScrollToFreeMap}
              onNavigateToCare={handleNavigateToCare}
            />

            {/* Bloco 3: Carrossel Interativo do Método GAIA (G-A-I-A) */}
            <GaiaMethod onOpenClubModal={handleOpenClub} />

            {/* Bloco 4: Porta 1 — Clube GAIA (24,97€/mês com Testemunhos) */}
            <ClubGaia onOpenClubModal={handleOpenClub} />

            {/* Bloco 5: Porta 3 — Mapa Gratuito + Sessão (Tally) */}
            <FreeMapSection onNavigateToCare={handleNavigateToCare} />

            {/* Bloco 6: Podcast "O Intestino Fala" */}
            <PodcastSection />

            {/* Bloco 7: Prova Social / Testemunhos Amplos */}
            <Testimonials />

            {/* Bloco 8: Sobre Dulce Canivari */}
            <About onOpenContactModal={() => {
              const el = document.getElementById('contactos');
              if (el) el.scrollIntoView({ behavior: 'smooth' });
            }} />

            {/* Bloco 9: Formulário e Contactos */}
            <ContactSection />
          </>
        )}

        {currentView === 'menopausa' && (
          <MenopausaCourse
            onBuyCourse={() => setIsCourseCheckoutOpen(true)}
            onBackToHome={handleNavigateHome}
          />
        )}

        {currentView === 'care' && (
          <PersonalizedCare onBackToHome={handleNavigateHome} />
        )}
      </main>

      {/* Rodapé Oficial */}
      <Footer
        onOpenClubModal={handleOpenClub}
        onNavigateToCourse={handleNavigateToCourse}
        onNavigateToCare={handleNavigateToCare}
        onNavigateHome={handleNavigateHome}
      />

      {/* Modal de Adesão ao Clube GAIA (24,97€/mês) */}
      {isClubModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#FDFBF7] max-w-lg w-full rounded-3xl p-6 sm:p-8 border-2 border-[#B86F4B] shadow-2xl relative space-y-6 text-left">
            <button
              onClick={() => setIsClubModalOpen(false)}
              className="absolute top-4 right-4 p-2 rounded-full text-[#6B4F3F] hover:bg-[#D8C4A8]/30 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="space-y-2">
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#B86F4B]/15 text-[#B86F4B] text-xs font-bold uppercase tracking-wider">
                <Sparkles className="w-3.5 h-3.5" />
                <span>Inscrição Oficial • Clube GAIA</span>
              </div>
              <h3 className="font-serif text-2xl font-bold text-[#3F5B45]">
                Bem-vinda ao Clube GAIA
              </h3>
              <p className="text-xs text-[#6B4F3F]/80">
                Acesso imediato à comunidade, aos encontros quinzenais ao vivo e ao protocolo anti-inflamatório completo.
              </p>
            </div>

            <div className="p-4 rounded-2xl bg-[#3F5B45]/10 border border-[#3F5B45]/20 space-y-2">
              <div className="flex items-center justify-between">
                <span className="font-serif text-2xl font-black text-[#3F5B45]">24,97€ / mês</span>
                <span className="text-[11px] text-[#A67878] font-bold uppercase">Sem fidelização</span>
              </div>
              <p className="text-xs text-[#6B4F3F]">
                Cobrança mensal segura com renovação automática e cancelamento simples em 1 clique a qualquer momento.
              </p>
            </div>

            <div className="space-y-2 text-xs text-[#6B4F3F]">
              <div className="flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 text-[#3F5B45]" />
                <span>Acesso imediato à plataforma de alunas e vídeos gravados</span>
              </div>
              <div className="flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 text-[#3F5B45]" />
                <span>Entrada no grupo exclusivo de suporte da comunidade</span>
              </div>
              <div className="flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 text-[#3F5B45]" />
                <span>Garantia total de satisfação de 14 dias</span>
              </div>
            </div>

            <div className="pt-2 space-y-3">
              <Button
                onClick={() => {
                  alert('A redirecionar para o checkout seguro da Stripe / MB WAY (24,97€/mês)...');
                  setIsClubModalOpen(false);
                }}
                className="w-full bg-[#B86F4B] hover:bg-[#a15f3e] text-white font-bold py-6 rounded-xl text-sm uppercase tracking-wider shadow-lg flex items-center justify-center gap-2"
              >
                <span>Finalizar Inscrição no Clube (24,97€)</span>
                <ArrowRight className="w-4 h-4" />
              </Button>
              <p className="text-center text-[11px] text-[#A67878] flex items-center justify-center gap-1">
                <ShieldCheck className="w-3.5 h-3.5" />
                <span>Pagamento 100% encriptado e certificado</span>
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Compra do Curso Meno(s)pausa (97€) */}
      {isCourseCheckoutOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#FDFBF7] max-w-md w-full rounded-3xl p-6 sm:p-8 border border-[#3F5B45] shadow-2xl relative space-y-5 text-left">
            <button
              onClick={() => setIsCourseCheckoutOpen(false)}
              className="absolute top-4 right-4 p-2 rounded-full text-[#6B4F3F] hover:bg-[#D8C4A8]/30 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="space-y-1">
              <span className="text-[11px] font-bold text-[#B86F4B] uppercase tracking-wider">
