  id: string;
  title: string;
  price: number;
  description: string;
  isRecurring?: boolean;
}

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: CheckoutProduct | null;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
