                  <AlertCircle className="w-4 h-4 flex-shrink-0" />
                  <span>{errorMessage}</span>
                </div>
              )}

              <div className="space-y-3">
                <div>
                  <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                    Nome Completo *
                  </label>
                  <input
                    type="text"
                    required
                    value={customerName}
                    onChange={(e) => setCustomerName(e.target.value)}
                    placeholder="Ex: Maria Silva"
                    className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                    E-mail (para receção dos acessos) *
                  </label>
                  <input
                    type="email"
                    required
                    value={customerEmail}
                    onChange={(e) => setCustomerEmail(e.target.value)}
                    placeholder="maria.silva@exemplo.pt"
                    className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                      Telemóvel (9 dígitos) *
                    </label>
                    <input
                      type="tel"
                      required
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="912 345 678"
                      className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                      NIF (Opcional p/ Fatura)
                    </label>
                    <input
                      type="text"
                      value={nif}
                      onChange={(e) => setNif(e.target.value)}
                      placeholder="123456789"
                      className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                    />
                  </div>
                </div>
              </div>

              {/* Escolha do Método de Pagamento */}
              <div className="pt-2">
                <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-2">
                  Método de Pagamento Português
                </label>
                <div className="grid grid-cols-2 gap-3">
                  <button
                    type="button"
                    onClick={() => setPaymentMethod('mbway')}
                    className={`p-3.5 rounded-2xl border-2 text-left flex flex-col justify-between transition-all ${
                      paymentMethod === 'mbway'
                        ? 'border-[#B86F4B] bg-[#B86F4B]/10 shadow-sm'
                        : 'border-[#D8C4A8] bg-white hover:border-[#B86F4B]/50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <Smartphone className={`w-5 h-5 ${paymentMethod === 'mbway' ? 'text-[#B86F4B]' : 'text-[#6B4F3F]'}`} />
                      <span className="text-[11px] font-bold uppercase tracking-wider text-[#B86F4B]">MB WAY</span>
                    </div>
                    <span className="text-[11px] text-[#6B4F3F]/80 mt-2 font-medium">Confirmação na app</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => setPaymentMethod('multibanco')}
                    className={`p-3.5 rounded-2xl border-2 text-left flex flex-col justify-between transition-all ${
                      paymentMethod === 'multibanco'
                        ? 'border-[#B86F4B] bg-[#B86F4B]/10 shadow-sm'
                        : 'border-[#D8C4A8] bg-white hover:border-[#B86F4B]/50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <CreditCard className={`w-5 h-5 ${paymentMethod === 'multibanco' ? 'text-[#B86F4B]' : 'text-[#6B4F3F]'}`} />
                      <span className="text-[11px] font-bold uppercase tracking-wider text-[#3F5B45]">Multibanco</span>
                    </div>
                    <span className="text-[11px] text-[#6B4F3F]/80 mt-2 font-medium">Entidade + Ref</span>
                  </button>
                </div>
              </div>

              {/* Botão de Submissão */}
              <Button
                type="submit"
                disabled={isLoading}
                className="w-full bg-[#3F5B45] hover:bg-[#324937] text-white py-3.5 rounded-xl font-bold text-sm tracking-wider uppercase shadow-md flex items-center justify-center gap-2 mt-4 transition-all transform active:scale-98"
              >
                {isLoading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    <span>A Gerar Pagamento...</span>
                  </>
                ) : (
                  <>
                    <Lock className="w-4 h-4" />
                    <span>CONCLUIR PAGAMENTO ({Number(product.price).toFixed(2)}€)</span>
                  </>
                )}
              </Button>

              <div className="flex items-center justify-center gap-4 text-[11px] text-[#6B4F3F]/70 pt-2">
                <span className="flex items-center gap-1">
                  <ShieldCheck className="w-3.5 h-3.5 text-emerald-600" />
                  Encriptação SSL 256-bit
                </span>
                <span>•</span>
                <span>Processado por Ifthenpay</span>
              </div>
            </form>
          </>
        ) : (
          /* Ecrã de Confirmação e Dados de Pagamento */
          <div className="space-y-5 animate-fade-in">
            <div className="text-center space-y-2">
              <div className="w-12 h-12 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center mx-auto">
                <CheckCircle2 className="w-6 h-6" />
              </div>
              <h3 className="font-serif text-2xl font-bold text-[#3F5B45]">
                {paymentResult.paymentMethod === 'mbway' ? 'Pedido MB WAY Enviado!' : 'Referência Multibanco Gerada!'}
              </h3>
              <p className="text-xs text-[#6B4F3F]/80 max-w-sm mx-auto">
                {paymentResult.message}
              </p>
            </div>

            {paymentResult.paymentMethod === 'mbway' ? (
              <Card className="p-5 bg-white border border-[#D8C4A8] rounded-2xl text-center space-y-3">
                <div className="flex items-center justify-center gap-2 text-[#B86F4B] font-semibold text-sm">
                  <Clock className="w-4 h-4 animate-pulse" />
                  <span>A aguardar validação na app MB WAY</span>
                </div>
                <p className="text-xs text-[#6B4F3F]/70">
                  Tens cerca de 5 minutos para aceitar a notificação de {Number(paymentResult.amount || product.price).toFixed(2)}€ no teu telemóvel.
                </p>
              </Card>
            ) : (
              <Card className="p-5 bg-white border border-[#D8C4A8] rounded-2xl space-y-4">
                <div className="flex items-center justify-between border-b border-[#D8C4A8]/40 pb-2">
                  <span className="text-xs text-[#6B4F3F]/70">Entidade:</span>
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-bold text-sm text-[#3F5B45]">{paymentResult.entity}</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(paymentResult.entity || '', 'entity')}
                      className="p-1 rounded text-[#6B4F3F] hover:bg-[#D8C4A8]/30"
                      title="Copiar Entidade"
                    >
                      {copiedEntity ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                  </div>
                </div>

                <div className="flex items-center justify-between border-b border-[#D8C4A8]/40 pb-2">
                  <span className="text-xs text-[#6B4F3F]/70">Referência:</span>
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-bold text-base text-[#B86F4B]">{paymentResult.reference}</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(paymentResult.reference || '', 'ref')}
                      className="p-1 rounded text-[#6B4F3F] hover:bg-[#D8C4A8]/30"
                      title="Copiar Referência"
                    >
                      {copiedRef ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-xs text-[#6B4F3F]/70">Montante:</span>
                  <span className="font-serif font-black text-lg text-[#3F5B45]">
                    {Number(paymentResult.amount || product.price).toFixed(2)}€
                  </span>
                </div>
              </Card>
            )}

            <div className="p-4 rounded-xl bg-[#3F5B45]/10 text-[#3F5B45] text-xs space-y-1">
              <p className="font-semibold">O que acontece a seguir?</p>
              <p className="text-[11px] text-[#6B4F3F]/80">
                Assim que o pagamento for detetado, receberás um e-mail com as instruções de boas-vindas e acesso imediato aos materiais.
              </p>
            </div>

            <Button
              type="button"
              onClick={handleResetAndClose}
              className="w-full bg-[#3F5B45] hover:bg-[#324937] text-white py-3 rounded-xl font-bold text-xs uppercase tracking-wider"
            >
              Concluir e Voltar
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};

