  reference?: string;
  entity?: string;
  amount?: number;
  expiryDate?: string;
}

export interface CheckoutProduct {
  id: string;
  title: string;
  price: number;
  description: string;
  isRecurring?: boolean;
}

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: CheckoutProduct | null;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen,
  onClose,
  product,
}) => {
  const [customerName, setCustomerName] = useState('');
  const [customerEmail, setCustomerEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [nif, setNif] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'mbway' | 'multibanco'>('mbway');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [paymentResult, setPaymentResult] = useState<PaymentResponse | null>(null);
  const [copiedEntity, setCopiedEntity] = useState(false);
  const [copiedRef, setCopiedRef] = useState(false);

  if (!isOpen || !product) return null;

  const handleCopy = (text: string, type: 'entity' | 'ref') => {
    if (typeof navigator !== 'undefined' && navigator.clipboard) {
      navigator.clipboard.writeText(text);
    }
    if (type === 'entity') {
      setCopiedEntity(true);
      setTimeout(() => setCopiedEntity(false), 2000);
    } else {
      setCopiedRef(true);
      setTimeout(() => setCopiedRef(false), 2000);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage('');

    if (!customerName.trim()) {
      setErrorMessage('Por favor, indica o teu nome completo.');
      return;
    }
    if (!customerEmail.trim() || !customerEmail.includes('@')) {
      setErrorMessage('Por favor, indica um e-mail válido.');
      return;
    }

    const cleanPhone = (phone || '').replace(/\D/g, '');
    if (cleanPhone.length < 9) {
      setErrorMessage('Por favor, insere um número de telemóvel com pelo menos 9 dígitos.');
      return;
    }

    setIsLoading(true);

    try {
      // Simulação de gateway seguro Ifthenpay / Supabase edge function
      await new Promise((resolve) => setTimeout(resolve, 900));

      if (paymentMethod === 'mbway') {
        setPaymentResult({
          success: true,
          paymentMethod: 'mbway',
          message: `Notificação enviada com sucesso para o telemóvel ${cleanPhone}. Abre a tua app MB WAY para confirmar o pagamento de ${Number(product.price).toFixed(2)}€.`,
          amount: product.price,
        });
      } else {
        // Geração de referência Multibanco mockada realista
        const mockRef = `${Math.floor(100 + Math.random() * 900)} ${Math.floor(100 + Math.random() * 900)} ${Math.floor(100 + Math.random() * 900)}`;
        setPaymentResult({
          success: true,
          paymentMethod: 'multibanco',
          entity: '21249',
          reference: mockRef,
          amount: product.price,
          expiryDate: '24 horas',
          message: 'Referência gerada com sucesso. Efetua o pagamento no teu homebanking ou terminal Multibanco.',
        });
      }
    } catch (err: unknown) {
      const error = err as Error;
      setErrorMessage(error?.message || 'Erro ao processar o pagamento. Tenta novamente.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetAndClose = () => {
    setPaymentResult(null);
    setErrorMessage('');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in overflow-y-auto">
      <div className="bg-[#FDFBF7] max-w-lg w-full rounded-3xl p-6 sm:p-8 border-2 border-[#B86F4B] shadow-2xl relative space-y-6 text-left my-8">
        {/* Botão de Fechar */}
        <button
          onClick={handleResetAndClose}
          className="absolute top-4 right-4 p-2 rounded-full text-[#6B4F3F] hover:bg-[#D8C4A8]/30 transition-colors"
          aria-label="Fechar"
        >
          <X className="w-5 h-5" />
        </button>

        {!paymentResult ? (
          <>
            {/* Cabeçalho */}
            <div className="space-y-1.5 pr-8">
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#3F5B45]/10 text-[#3F5B45] text-xs font-bold uppercase tracking-wider">
                <Sparkles className="w-3.5 h-3.5 text-[#B86F4B]" />
                <span>Checkout Seguro • Ifthenpay</span>
              </div>
              <h3 className="font-serif text-2xl font-bold text-[#3F5B45]">
                {product.title}
              </h3>
              <p className="text-xs text-[#6B4F3F]/80">
                {product.description}
              </p>
            </div>

            {/* Resumo de Valor */}
            <div className="p-4 rounded-2xl bg-[#3F5B45]/10 border border-[#3F5B45]/20 flex items-center justify-between">
              <div>
                <p className="text-xs text-[#6B4F3F] font-medium">Total a pagar</p>
                <p className="font-serif text-3xl font-black text-[#3F5B45]">
                  {Number(product.price).toFixed(2)}€
                  {product.isRecurring && <span className="text-xs font-normal text-[#6B4F3F] ml-1">/ mês</span>}
                </p>
              </div>
              <div className="text-right">
                <span className="text-[11px] bg-[#3F5B45] text-white px-2.5 py-1 rounded-full font-bold uppercase tracking-wider">
                  Acesso Imediato
                </span>
              </div>
            </div>

            {/* Formulário de Dados */}
            <form onSubmit={handleSubmit} className="space-y-4">
              {errorMessage && (
                <div className="p-3 rounded-xl bg-rose-50 border border-rose-200 text-rose-700 text-xs font-medium flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" />
                  <span>{errorMessage}</span>
                </div>
              )}

              <div className="space-y-3">
                <div>
                  <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                    Nome Completo *
                  </label>
                  <input
                    type="text"
                    required
                    value={customerName}
                    onChange={(e) => setCustomerName(e.target.value)}
                    placeholder="Ex: Maria Silva"
                    className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                    E-mail (para receção dos acessos) *
                  </label>
                  <input
                    type="email"
                    required
                    value={customerEmail}
                    onChange={(e) => setCustomerEmail(e.target.value)}
                    placeholder="maria.silva@exemplo.pt"
                    className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                      Telemóvel (9 dígitos) *
                    </label>
                    <input
                      type="tel"
                      required
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="912 345 678"
                      className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-1">
                      NIF (Opcional p/ Fatura)
                    </label>
                    <input
                      type="text"
                      value={nif}
                      onChange={(e) => setNif(e.target.value)}
                      placeholder="123456789"
                      className="w-full px-3.5 py-2.5 rounded-xl border border-[#D8C4A8] bg-white text-sm text-[#6B4F3F] focus:outline-none focus:ring-2 focus:ring-[#B86F4B]"
                    />
                  </div>
                </div>
              </div>

              {/* Escolha do Método de Pagamento */}
              <div className="pt-2">
                <label className="block text-xs font-semibold text-[#6B4F3F] uppercase tracking-wider mb-2">
                  Método de Pagamento Português
                </label>
                <div className="grid grid-cols-2 gap-3">
                  <button
                    type="button"
                    onClick={() => setPaymentMethod('mbway')}
                    className={`p-3.5 rounded-2xl border-2 text-left flex flex-col justify-between transition-all ${
                      paymentMethod === 'mbway'
                        ? 'border-[#B86F4B] bg-[#B86F4B]/10 shadow-sm'
                        : 'border-[#D8C4A8] bg-white hover:border-[#B86F4B]/50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <Smartphone className={`w-5 h-5 ${paymentMethod === 'mbway' ? 'text-[#B86F4B]' : 'text-[#6B4F3F]'}`} />
                      <span className="text-[11px] font-bold uppercase tracking-wider text-[#B86F4B]">MB WAY</span>
                    </div>
                    <span className="text-[11px] text-[#6B4F3F]/80 mt-2 font-medium">Confirmação na app</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => setPaymentMethod('multibanco')}
                    className={`p-3.5 rounded-2xl border-2 text-left flex flex-col justify-between transition-all ${
                      paymentMethod === 'multibanco'
                        ? 'border-[#B86F4B] bg-[#B86F4B]/10 shadow-sm'
                        : 'border-[#D8C4A8] bg-white hover:border-[#B86F4B]/50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <CreditCard className={`w-5 h-5 ${paymentMethod === 'multibanco' ? 'text-[#B86F4B]' : 'text-[#6B4F3F]'}`} />
