              <div className="w-12 h-12 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center mx-auto">
                <CheckCircle2 className="w-6 h-6" />
              </div>
              <h3 className="font-serif text-2xl font-bold text-[#3F5B45]">
                {paymentResult.paymentMethod === 'mbway' ? 'Pedido MB WAY Enviado!' : 'Referência Multibanco Gerada!'}
              </h3>
              <p className="text-xs text-[#6B4F3F]/80 max-w-sm mx-auto">
                {paymentResult.message}
              </p>
            </div>

            {paymentResult.paymentMethod === 'mbway' ? (
              <Card className="p-5 bg-white border border-[#D8C4A8] rounded-2xl text-center space-y-3">
                <div className="flex items-center justify-center gap-2 text-[#B86F4B] font-semibold text-sm">
                  <Clock className="w-4 h-4 animate-pulse" />
                  <span>A aguardar validação na app MB WAY</span>
                </div>
                <p className="text-xs text-[#6B4F3F]/70">
                  Tens cerca de 5 minutos para aceitar a notificação de {Number(paymentResult.amount || product.price).toFixed(2)}€ no teu telemóvel.
                </p>
              </Card>
            ) : (
              <Card className="p-5 bg-white border border-[#D8C4A8] rounded-2xl space-y-4">
                <div className="flex items-center justify-between border-b border-[#D8C4A8]/40 pb-2">
                  <span className="text-xs text-[#6B4F3F]/70">Entidade:</span>
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-bold text-sm text-[#3F5B45]">{paymentResult.entity}</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(paymentResult.entity || '', 'entity')}
                      className="p-1 rounded text-[#6B4F3F] hover:bg-[#D8C4A8]/30"
                      title="Copiar Entidade"
                    >
                      {copiedEntity ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                  </div>
                </div>

                <div className="flex items-center justify-between border-b border-[#D8C4A8]/40 pb-2">
                  <span className="text-xs text-[#6B4F3F]/70">Referência:</span>
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-bold text-base text-[#B86F4B]">{paymentResult.reference}</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(paymentResult.reference || '', 'ref')}
                      className="p-1 rounded text-[#6B4F3F] hover:bg-[#D8C4A8]/30"
                      title="Copiar Referência"
                    >
                      {copiedRef ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-xs text-[#6B4F3F]/70">Montante:</span>
                  <span className="font-serif font-black text-lg text-[#3F5B45]">
                    {Number(paymentResult.amount || product.price).toFixed(2)}€
                  </span>
                </div>
              </Card>
            )}

            <div className="p-4 rounded-xl bg-[#3F5B45]/10 text-[#3F5B45] text-xs space-y-1">
              <p className="font-semibold">O que acontece a seguir?</p>
              <p className="text-[11px] text-[#6B4F3F]/80">
                Assim que o pagamento for detetado, receberás um e-mail com as instruções de boas-vindas e acesso imediato aos materiais.
              </p>
            </div>

            <Button
              type="button"
              onClick={handleResetAndClose}
              className="w-full bg-[#3F5B45] hover:bg-[#324937] text-white py-3 rounded-xl font-bold text-xs uppercase tracking-wider"
            >
              Concluir e Voltar
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};

